import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.B45avKwg.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"GenSense","text":"Semantic Analysis Engine","tagline":"Detect logical flaws, security risks, and AI-generated code patterns that conventional linters miss.","actions":[{"theme":"brand","text":"Get Started","link":"/guide"},{"theme":"alt","text":"Rule Catalog","link":"/rules"},{"theme":"alt","text":"Write Custom Rules","link":"/extending"}]},"features":[{"title":"Semantic Program Graph","details":"SPG exposes a cross-file symbol graph with call edges, temporal event chains, and taint flow edges to every rule — enabling algebraic query composition without Datalog."},{"title":"CSA Body Analysis","details":"Contextual Structural Analysis checks function bodies for required patterns (body_must_contain) and delegation suppression (body_may_delegate_via) — catches validation gaps, missing auth, and sanitizer passthrough."},{"title":"Extensible Rule Engine","details":"Ship custom YAML rules without recompiling. Drop a .yml file in .gensense/rules/ and the engine picks it up automatically at startup."},{"title":"Temporal & Taint Analysis","details":"Detects event-ordering violations (mutex locks held across await, connection leaks) and tracks data flow from sensitive sources to unsafe sinks across function boundaries."},{"title":"Native Performance","details":"Built in Rust with optimized single-pass rule execution. Scans a 50-file project in under 5 seconds on standard hardware."},{"title":"CI/CD Ready","details":"JSON, SARIF, strict-mode, diff-only, baseline comparison, and suite selection. Integrates with GitHub Actions, pre-commit hooks, and VS Code."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(r,e,l,c,u,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h2 id="who-uses-gensense" tabindex="-1">Who Uses GenSense <a class="header-anchor" href="#who-uses-gensense" aria-label="Permalink to &quot;Who Uses GenSense&quot;">​</a></h2><h3 id="organizations-with-ai-assisted-development" tabindex="-1">Organizations with AI-Assisted Development <a class="header-anchor" href="#organizations-with-ai-assisted-development" aria-label="Permalink to &quot;Organizations with AI-Assisted Development&quot;">​</a></h3><p>Developers use GitHub Copilot, Claude, ChatGPT for code generation. GenSense catches AI-generated placeholder code, dead results, and tautological logic before they reach production.</p><h3 id="critical-infrastructure-teams" tabindex="-1">Critical Infrastructure Teams <a class="header-anchor" href="#critical-infrastructure-teams" aria-label="Permalink to &quot;Critical Infrastructure Teams&quot;">​</a></h3><p>Banking, healthcare, IoT systems cannot tolerate deadlocks and secret leaks. GenSense finds concurrency hazards and data leaks that traditional linters miss.</p><h3 id="platform-devops-teams" tabindex="-1">Platform &amp; DevOps Teams <a class="header-anchor" href="#platform-devops-teams" aria-label="Permalink to &quot;Platform &amp; DevOps Teams&quot;">​</a></h3><p>Enforce architectural patterns across teams without source recompilation. Custom rules as YAML files, hot-loaded at startup.</p><h3 id="security-auditors" tabindex="-1">Security Auditors <a class="header-anchor" href="#security-auditors" aria-label="Permalink to &quot;Security Auditors&quot;">​</a></h3><p>Scan for hardcoded secrets and unsafe patterns. Generate SARIF compliance reports with GitHub integration.</p><hr><h2 id="quick-evaluation" tabindex="-1">Quick Evaluation <a class="header-anchor" href="#quick-evaluation" aria-label="Permalink to &quot;Quick Evaluation&quot;">​</a></h2><p>Does this describe your scenario?</p><blockquote><p>&quot;Our team uses Copilot for code generation, and we&#39;re worried about production issues.&quot;</p></blockquote><p>✅ <strong>GenSense is built for this</strong></p><blockquote><p>&quot;We have strict typing but still get runtime deadlocks in async code.&quot;</p></blockquote><p>✅ <strong>GenSense will help</strong></p><blockquote><p>&quot;We want to enforce that all database queries use prepared statements.&quot;</p></blockquote><p>✅ <strong>Write a custom YAML rule</strong></p><blockquote><p>&quot;We have only synchronous Python code with no security risks.&quot;</p></blockquote><p>❌ <strong>GenSense won&#39;t add value</strong> (also doesn&#39;t support Python yet)</p>',20)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
